// Get ALL items directly from Merge Analysis Results
const inputs = $('Merge Analysis Results').all();

const clauseData = inputs[0]?.json?.output?.clauses || [];
const riskData = inputs[1]?.json?.output?.risks || [];

// Your Obligation Agent currently puts the JSON strings in `cities`
const rawObligations = inputs[2]?.json?.output?.cities || [];

const obligationData = rawObligations
  .map(item => {
    try {
      return typeof item === 'string' ? JSON.parse(item) : item;
    } catch {
      return null;
    }
  })
  .filter(Boolean);

const summaryData = inputs[3]?.json?.output || {};


// Risk weights
const riskWeights = {
  payment_terms: 0.25,
  liability: 0.30,
  termination: 0.15,
  ip: 0.15,
  confidentiality: 0.10,
  warranty: 0.03,
  indemnification: 0.02
};

// Risk level scores
const riskScores = {
  critical: 1.0,
  high: 0.75,
  medium: 0.5,
  low: 0.25,
  none: 0.0
};

let scoreBreakdown = {};
let totalWeightedScore = 0;
let redFlags = [];
let recommendations = [];

function normalizeRiskType(type) {
  const value = String(type || '').toLowerCase();

  if (value.includes('payment')) return 'payment_terms';
  if (value.includes('liability')) return 'liability';
  if (value.includes('termination') || value.includes('term and renewal')) {
    return 'termination';
  }
  if (value.includes('ip') || value.includes('intellectual property')) {
    return 'ip';
  }
  if (value.includes('confidential')) return 'confidentiality';
  if (value.includes('warranty')) return 'warranty';
  if (value.includes('indemn')) return 'indemnification';

  return null;
}

riskData.forEach(risk => {
  const category = normalizeRiskType(risk.clause_type);
  const weight = category ? riskWeights[category] : 0.01;

  const level = String(risk.risk_level || '').toLowerCase();
  const score = riskScores[level] ?? 0;

  totalWeightedScore += score * weight;

  if (category) {
    scoreBreakdown[category + '_risk'] = score;
  }

  if (level === 'critical' || level === 'high') {
    if (risk.risk_description) {
      redFlags.push(risk.risk_description);
    }

    if (risk.recommendation) {
      recommendations.push(risk.recommendation);
    }
  }
});


// Check for missing critical clauses
const criticalClauses = [
  'payment_terms',
  'liability',
  'termination'
];

const foundClauses = clauseData.map(
  c => String(c.clause_type || '').toLowerCase()
);

criticalClauses.forEach(critical => {
  if (!foundClauses.includes(critical)) {
    redFlags.push(`Missing critical clause: ${critical}`);
    recommendations.push(`Add ${critical} clause to contract`);
  }
});


// Check AI confidence
const lowConfidenceItems = [
  ...clauseData,
  ...riskData
].filter(
  item => Number(item.ai_confidence ?? 1) < 0.6
);

if (lowConfidenceItems.length > 0) {
  redFlags.push(
    `${lowConfidenceItems.length} items flagged for manual legal review`
  );

  recommendations.push(
    'Schedule legal review for low-confidence extractions'
  );
}


// Final output
return [
  {
    json: {
      clauses: clauseData,
      risks: riskData,
      obligations: obligationData,
      summary: summaryData,

      overall_risk_score:
        Math.round(totalWeightedScore * 100) / 100,

      score_breakdown: scoreBreakdown,
      red_flags: redFlags,
      recommendations: recommendations,

      calculated_at: new Date().toISOString()
    }
  }
];

