// Extract data from merged inputs
const inputs = $input.all();

const clauseData = inputs[0]?.json?.output?.clauses || [];
const riskData = inputs[1]?.json?.output?.risks || [];
const obligationData = inputs[2]?.json?.output?.obligations || [];
const summaryData = inputs[3]?.json?.output || {};

// Risk weights by the EXACT clause_type values
// returned by the Risk Assessment Agent.
const riskWeights = {
  'Service Level and Support (Clause 3)': 0.16,
  'Fees and Payment (Clause 4)': 0.08,
  'Data Protection and Security (Clause 5)': 0.18,
  'Confidentiality (Clause 6)': 0.05,
  'Intellectual Property (Clause 7)': 0.08,
  'Indemnification (Clause 8)': 0.10,
  'Limitation of Liability (Clause 9)': 0.22,
  'Term, Renewal and Termination (Clause 10)': 0.10,
  'Effect of Termination (Clause 11)': 0.02,
  'General / Governing Law (Clause 12)': 0.01,
  'Definitions and Interpretation (Clause 1)': 0.00,
  'Services and Obligations (Clause 2)': 0.00
};

// Risk level scores
const riskScores = {
  critical: 1.0,
  high: 0.75,
  medium: 0.5,
  low: 0.25,
  none: 0.0
};

// Calculate weighted risk score
let scoreBreakdown = {};
let totalWeightedScore = 0;

let redFlags = [];
let recommendations = [];

riskData.forEach(risk => {
  const weight = riskWeights[risk.clause_type] ?? 0;
  const score = riskScores[risk.risk_level?.toLowerCase()] ?? 0;

  const weightedScore = score * weight;

  scoreBreakdown[risk.clause_type + '_risk'] = score;

  totalWeightedScore += weightedScore;

  // High and critical risks become red flags
  if (
    risk.risk_level?.toLowerCase() === 'critical' ||
    risk.risk_level?.toLowerCase() === 'high'
  ) {
    redFlags.push(risk.risk_description);
    recommendations.push(risk.recommendation);
  }
});

// Check for missing critical clauses
const criticalClauses = [
  'payment_terms',
  'liability',
  'termination'
];

const foundClauses = clauseData.map(c => c.clause_type);

criticalClauses.forEach(critical => {
  if (!foundClauses.includes(critical)) {
    redFlags.push(`Missing critical clause: ${critical}`);
    recommendations.push(`Add ${critical} clause to contract`);
  }
});

// Check AI confidence levels
const lowConfidenceItems = [
  ...clauseData,
  ...riskData
].filter(item => {
  return typeof item.ai_confidence === 'number' &&
         item.ai_confidence < 0.6;
});

if (lowConfidenceItems.length > 0) {
  redFlags.push(
    `${lowConfidenceItems.length} items flagged for manual legal review (low AI confidence)`
  );

  recommendations.push(
    'Schedule legal review for low-confidence extractions'
  );
}

// Final risk score
const overallRiskScore =
  Math.round(totalWeightedScore * 100) / 100;

return {
  clauses: clauseData,
  risks: riskData,
  obligations: obligationData,
  summary: summaryData,

  overall_risk_score: overallRiskScore,

  score_breakdown: scoreBreakdown,

  red_flags: redFlags,

  recommendations: recommendations,

  calculated_at: new Date().toISOString(),
  contractId: inputs[0]?.json?.contractId || inputs[1]?.json?.contractId || inputs[2]?.json?.contractId || inputs[3]?.json?.contractId || null
};

